1	import { afterAll, beforeAll, describe, expect, setDefaultTimeout, test } from "bun:test";
2	import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
3	import { tmpdir } from "node:os";
4	import { join } from "node:path";
5	
6	import { identify } from "../src/identity/index.ts";
7	import { parseCheckpoints } from "../src/ingest/parse.ts";
8	import { priceSession } from "../src/price/index.ts";
9	import {
10	  aggregateBySetup,
11	  maturity,
12	  outcomesReport,
13	  scoreSessions,
14	  UNKNOWN_SETUP,
15	  type ScoredOutcome,
16	} from "../src/score/index.ts";
17	import type { Session } from "../src/types.ts";
18	import { checkReport, sumcheck } from "../scripts/sumcheck.ts";
19	import { git, makeFixture, type FixtureTruth } from "./fixtures/make-fixture.ts";
20	
21	// Building a fixture and scoring it spawns git a few hundred times.
22	setDefaultTimeout(60_000);
23	
24	const root = mkdtempSync(join(tmpdir(), "roster-score-outcomes-"));
25	afterAll(() => rmSync(root, { recursive: true, force: true }));
26	
27	let dir: string;
28	let truth: FixtureTruth;
29	let sessions: Session[];
30	/** Fixture setup key (from the prompt tag) → inferred setup id. */
31	const setupOf: Record<string, string> = {};
32	
33	function load(repo: string): Session[] {
34	  return parseCheckpoints(repo, "branch", { warn: () => {} }).map((s) => {
35	    const id = identify(s, repo);
36	    if (id.tag && id.setupId) setupOf[id.tag.setup] = id.setupId;
37	    return { ...s, setup_id: id.setupId };
38	  });
39	}
40	
41	const sha = (subject: string) => {
42	  const c = truth.commits.find((x) => x.subject === subject);
43	  if (!c) throw new Error(`no fixture commit "${subject}"`);
44	  return c.sha;
45	};
46	/** A copy of the fixture whose HEAD is reset to `subject`, to see the repo as it was then. */
47	let copies = 0;
48	function copyAt(subject: string): string {
49	  const d = join(root, `copy-${copies++}`);
50	  git(root, ["clone", "-q", "--no-local", dir, d]);
51	  git(d, ["fetch", "-q", "origin", "entire/checkpoints/v1:entire/checkpoints/v1"]);
52	  git(d, ["reset", "-q", "--hard", sha(subject)]);
53	  return d;
54	}
55	const byCommit = (rows: ScoredOutcome[], subject: string) => rows.filter((o) => o.commit_sha === sha(subject));
56	
57	beforeAll(() => {
58	  dir = join(root, "multisession");
59	  truth = makeFixture(dir, "multisession");
60	  sessions = load(dir);
61	});
62	
63	describe("scoreSessions on the multisession fixture", () => {
64	  let rows: ScoredOutcome[];
65	  beforeAll(() => {
66	    rows = scoreSessions(dir, sessions);
67	  });
68	
69	  test("one row per session", () => {
70	    expect(rows.map((o) => o.session_id).sort()).toEqual(sessions.map((s) => s.id).sort());
71	  });
72	
73	  test("expected table", () => {
74	    const table = rows
75	      .map((o) => ({
76	        commit: truth.commits.find((c) => c.sha === o.commit_sha)?.subject ?? null,
77	        setup: Object.keys(setupOf).find((k) => setupOf[k] === o.setup_id) ?? null,
78	        status: o.status,
79	        censored: o.censored,
80	        survival: o.survival === null ? null : Math.round(o.survival * 1000) / 1000,
81	        reverted: o.reverted,
82	        rework_human: o.rework_human === null ? null : Math.round(o.rework_human * 1000) / 1000,
83	        rework_agent: o.rework_agent,
84	        unattended: o.unattended,
85	      }))
86	      .sort((a, b) => `${a.commit}${a.setup}`.localeCompare(`${b.commit}${b.setup}`));
87	    expect(table).toEqual([
88	      // alpha: 10 of 30 lines rewritten by a human; the session took three prompts over three commits.
89	      { commit: "add alpha", setup: "X", status: "mature", censored: null, survival: 0.667, reverted: false, rework_human: 0.333, rework_agent: 0, unattended: false },
90	      { commit: "add beta", setup: "Y", status: "mature", censored: null, survival: 1, reverted: false, rework_human: 0, rework_agent: 0, unattended: false },
91	      { commit: "add delta", setup: "Y", status: "mature", censored: null, survival: 1, reverted: false, rework_human: 0, rework_agent: 0, unattended: true },
92	      { commit: "add delta", setup: "Z", status: "mature", censored: null, survival: 1, reverted: false, rework_human: 0, rework_agent: 0, unattended: true },
93	      // gamma: reverted by a human commit, which also counts as human rework of every line.
94	      { commit: "add gamma", setup: "Z", status: "mature", censored: null, survival: 0, reverted: true, rework_human: 1, rework_agent: 0, unattended: true },
95	      // The orphan checkpoint has no commit: kept, with no metrics.
96	      { commit: null, setup: "Y", status: "too_young", censored: "no_commit", survival: null, reverted: null, rework_human: null, rework_agent: null, unattended: null },
97	    ]);
98	  });
99	
100	  test("cost comes from src/price; an unknown model gives null", () => {
101	    for (const s of sessions) {
102	      const o = rows.find((r) => r.session_id === s.id)!;
103	      const expected = priceSession(s.model, {
104	        input: s.tokens_in,
105	        output: s.tokens_out,
106	        cache_read: s.cache_read,
107	        cache_write: s.cache_write,
108	      }).usd;
109	      expect(o.cost_usd).toBe(expected);
110	    }
111	    expect(rows.every((o) => typeof o.cost_usd === "number" && o.cost_usd > 0)).toBe(true);
112	    const unknown = { ...sessions[0]!, model: "unknown" };
113	    expect(scoreSessions(dir, [unknown])[0]!.cost_usd).toBeNull();
114	  });
115	
116	  test("a session's own cost_usd wins over re-pricing", () => {
117	    const s = { ...sessions.find((x) => x.commit_sha === null)!, cost_usd: 1.25 };
118	    expect(scoreSessions(dir, [s])[0]!.cost_usd).toBe(1.25);
119	  });
120	});
121	
122	describe("maturity censoring", () => {
123	  test("commits with fewer than 5 first-parent commits after them are too_young with null metrics", () => {
124	    // HEAD at the human rework: delta has 1 commit after it, alpha has 5.
125	    const d = copyAt("human: rework src/alpha.ts");
126	    const rows = scoreSessions(d, load(d));
127	    for (const o of byCommit(rows, "add delta")) {
128	      expect(o).toMatchObject({ status: "too_young", censored: "too_young", survival: null, reverted: null, rework_human: null, rework_agent: null, unattended: null });
129	      expect(o.cost_usd).toBe(rows.find((r) => r.session_id === o.session_id)!.cost_usd);
130	    }
131	    expect(byCommit(rows, "add alpha")[0]!.status).toBe("mature");
132	    expect(byCommit(rows, "add gamma")[0]!.status).toBe("too_young"); // 2 after it
133	  });
134	
135	  test("5 newer commits are not enough when HEAD is under 6 h younger", () => {
136	    const d = copyAt("add epsilon");
137	    const epsilonAt = Date.parse(truth.commits.find((c) => c.subject === "add epsilon")!.date);
138	    const commitAt = (offsetH: number, i: number) => {
139	      writeFileSync(join(d, `late-${i}.md`), `${i}\n`);
140	      git(d, ["add", "-A"]);
141	      const at = new Date(epsilonAt + offsetH * 3600 * 1000).toISOString();
142	      git(d, ["commit", "-q", "--no-gpg-sign", "-m", `late ${i}`], { env: { GIT_AUTHOR_DATE: at, GIT_COMMITTER_DATE: at } });
143	    };
144	    for (let i = 0; i < 5; i++) commitAt(1, i);
145	    expect(maturity(d, sha("add epsilon"))).toBe("too_young");
146	    commitAt(5.99, 5);
147	    expect(maturity(d, sha("add epsilon"))).toBe("too_young");
148	    commitAt(6, 6);
149	    expect(maturity(d, sha("add epsilon"))).toBeNull();
150	  });
151	
152	  test("a commit that HEAD does not contain is censored as not_on_head", () => {
153	    const d = copyAt("add beta");
154	    expect(maturity(d, sha("add delta"))).toBe("not_on_head");
155	  });
156	});
157	
158	describe("aggregateBySetup", () => {
159	  let rows: ScoredOutcome[];
160	  beforeAll(() => {
161	    rows = scoreSessions(dir, sessions);
162	  });
163	
164	  test("per-setup counts, survival and cost_per_surviving_change", () => {
165	    const agg = Object.fromEntries(aggregateBySetup(rows).map((a) => [a.setup_id, a]));
166	    const x = agg[setupOf.X!]!;
167	    const y = agg[setupOf.Y!]!;
168	    const z = agg[setupOf.Z!]!;
169	    expect([x.sessions, x.mature, x.too_young, x.reverted, x.unattended]).toEqual([1, 1, 0, 0, 0]);
170	    expect([y.sessions, y.mature, y.too_young, y.reverted, y.unattended]).toEqual([3, 2, 1, 0, 1]);
171	    expect([z.sessions, z.mature, z.too_young, z.reverted, z.unattended]).toEqual([2, 2, 0, 1, 2]);
172	    expect(x.survival_sum).toBeCloseTo(20 / 30, 10);
173	    expect(y.survival_mean).toBe(1);
174	    expect(z.survival_sum).toBe(1);
175	
176	    const cost = (setup: string, mature: boolean) =>
177	      rows.filter((o) => o.setup_id === setup && (!mature || o.status === "mature")).reduce((a, o) => a + o.cost_usd!, 0);
178	    expect(x.cost_usd).toBeCloseTo(cost(setupOf.X!, false), 12);
179	    expect(x.cost_per_surviving_change).toBeCloseTo(cost(setupOf.X!, true) / (20 / 30), 12);
180	    // Y's orphan session costs money but is not mature: it counts in cost_usd, not in cost per surviving change.
181	    expect(y.cost_usd).toBeCloseTo(cost(setupOf.Y!, false), 12);
182	    expect(y.cost_per_surviving_change).toBeCloseTo(cost(setupOf.Y!, true) / 2, 12);
183	    expect(y.cost_usd!).toBeGreaterThan(cost(setupOf.Y!, true));
184	    // gamma survived 0 and delta 1: Z pays for both over one surviving change.
185	    expect(z.cost_per_surviving_change).toBeCloseTo(cost(setupOf.Z!, true), 12);
186	    expect(z.cost_unknown).toBe(0);
187	  });
188	
189	  test("an unknown cost leaves the setup's cost per surviving change null, not a partial sum", () => {
190	    const zRows = rows.filter((o) => o.setup_id === setupOf.Z).map((o, i) => (i === 0 ? { ...o, cost_usd: null } : o));
191	    const [z] = aggregateBySetup(zRows);
192	    expect(z!.cost_unknown).toBe(1);
193	    expect(z!.cost_usd).toBe(zRows[1]!.cost_usd);
194	    expect(z!.cost_per_surviving_change).toBeNull();
195	  });
196	
197	  test("sessions without a setup go to the unknown bucket; zero survival gives null cost per change", () => {
198	    const o: ScoredOutcome = { ...rows.find((r) => r.reverted)!, setup_id: null, cost_usd: 2 };
199	    const [a] = aggregateBySetup([o]);
200	    expect(a!.setup_id).toBe(UNKNOWN_SETUP);
201	    expect(a!.cost_usd).toBe(2);
202	    expect(a!.cost_per_surviving_change).toBeNull();
203	  });
