205	  test("the exported report passes scripts/sumcheck.ts", () => {
206	    const report = outcomesReport(rows);
207	    expect(report.sessions.total).toBe(6);
208	    expect(report.mature.total).toBe(5);
209	    expect(report.too_young.total).toBe(1);
210	    expect(Object.keys(report.cost_by_setup).sort()).toEqual([setupOf.X!, setupOf.Y!, setupOf.Z!].sort());
